function typeformContactSubmission({ response, nameQuestion, emailQuestion }) {
  if (!response || !Array.isArray(response.definition?.fields) || !Array.isArray(response.answers))
    throw new Error("Expected the complete Typeform submission");
  const read = (selector, type) => {
    if (typeof selector !== "string" || !selector)
      throw new Error("Configure the contact question selector");
    const fields = response.definition.fields.filter(
      (field) => field?.id === selector || field?.ref === selector || field?.title === selector,
    );
    if (
      fields.length !== 1 ||
      typeof fields[0].id !== "string" ||
      !fields[0].id ||
      response.definition.fields.filter((field) => field?.id === fields[0].id).length !== 1
    )
      throw new Error("The contact question must identify exactly one form field");
    const answers = response.answers.filter((answer) => answer?.field?.id === fields[0].id);
    if (
      answers.length !== 1 ||
      answers[0].type !== type ||
      typeof answers[0][type] !== "string" ||
      !answers[0][type].trim()
    )
      throw new Error("Expected one nonempty " + type + " answer for the contact question");
    return answers[0][type];
  };
  const fields = { Name: read(nameQuestion, "text"), Email: read(emailQuestion, "email") };
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.Email))
    throw new Error("The contact email must be a valid address");
  return { fields, records: [{ fields }], parts: contactNotificationParts(fields) };
}

function contactNotificationParts(fields) {
  const text = "*New Submission* 🙌\nName: " + fields.Name + "\nEmail: " + fields.Email,
    chunks = [];
  let chunk = "";
  for (const character of text) {
    if (chunk.length + character.length > 3900) {
      chunks.push(chunk);
      chunk = "";
    }
    chunk += character;
  }
  if (chunk) chunks.push(chunk);
  const parts = chunks.map((content, index) =>
    chunks.length > 1 ? "Part " + (index + 1) + "/" + chunks.length + "\n" + content : content,
  );
  if (parts.some((part) => part.length > 4000))
    throw new Error("The contact notification part exceeds the message budget");
  return parts;
}

if ($json.event_type !== "form_response") throw new Error("Expected a completed Typeform response");
return {
  json: typeformContactSubmission({
    response: $json.form_response,
    nameQuestion: "Let's start with your name.",
    emailQuestion: "What's your email address?",
  }).fields,
};

function airtableFormRecord({ records }) {
  if (
    !Array.isArray(records) ||
    records.length !== 1 ||
    typeof records[0]?.id !== "string" ||
    !records[0].id ||
    !records[0].fields ||
    typeof records[0].fields !== "object" ||
    Array.isArray(records[0].fields)
  )
    throw new Error(
      "Airtable did not confirm one saved record; creation may already have occurred",
    );
  return { record: records[0] };
}

