const items = $input.all();
if (items.length !== 1) throw new Error("Expected one created contact record");
const record = airtableFormRecord({ records: [items[0].json] }).record;
const fields = $("Read the name and email answers").first().json;
const parts = contactNotificationParts(fields);
return parts.map((text, index) => ({
  json: { record, text, index: index + 1 },
  pairedItem: { item: 0 },
}));

const requests = $("Confirm the saved contact record").all();
if (!Number.isInteger($runIndex) || $runIndex < 0 || $runIndex >= requests.length)
  throw new Error("Invalid contact message index");
const request = requests[$runIndex].json,
  channel = $("Notify the Slack channel").params.channel;
if (
  $json.ok !== true ||
  typeof $json.ts !== "string" ||
  !/^\d+\.\d+$/.test($json.ts) ||
  $json.channel !== channel
)
  throw new Error(
    "Slack did not confirm the contact notice; the record and earlier messages may already exist",
  );
return { json: { record: request.record, part: request.index, message: $json } };
